def pair_sum(nums, target):
    """Return indices of two values summing to target, or None.
    >>> pair_sum([2, 7, 11, 15], 9)
    (0, 1)
    """
    seen = {}
    for i, n in enumerate(nums):
        if target - n in seen:
            return (seen[target - n], i)
        seen[n] = i
    return None
```

