def count_words(text):
    """Return a dict of word counts, case-insensitive, ignoring punctuation.
    >>> count_words('The cat sat on the mat. The cat purred.')
    {'the': 3, 'cat': 2, 'sat': 1, 'on': 1, 'mat': 1, 'purred': 1}
    """
    import re
    counts = {}
    for w in re.findall(r"[a-zA-Z']+", text.lower()):
        counts[w] = counts.get(w, 0) + 1
    return counts
```

