def has_cycle(adj):
    """adj is a dict node -> list of next nodes. Return True iff a cycle exists.
    >>> has_cycle({0: [1], 1: [2], 2: [0]})
    True
    >>> has_cycle({0: [1], 1: [2], 2: []})
    False
    """
    WHITE, GRAY, BLACK = 0, 1, 2
    color = {n: WHITE for n in adj}
    def visit(u):
        color[u] = GRAY
        for v in adj.get(u, []):
            if color.get(v, WHITE) == GRAY:
                return True
            if color.get(v, WHITE) == WHITE and visit(v):
                return True
        color[u] = BLACK
        return False
    return any(color[u] == WHITE and visit(u) for u in adj)
```

