def flatten_dict(d, sep='.'):
    """Flatten a nested dict; keys joined by sep.
    >>> flatten_dict({'a': {'b': 1, 'c': 2}, 'd': 3})
    {'a.b': 1, 'a.c': 2, 'd': 3}
    """
    result = {}
    def walk(prefix, val):
        if isinstance(val, dict):
            for k, v in val.items():
                walk(f'{prefix}{sep}{k}' if prefix else k, v)
        else:
            result[prefix] = val
    walk('', d)
    return result
```

