def num_islands(grid):
    """Count islands ('1') in a 2D grid (4-connected). Grid is list of lists of '0'/'1'.
    >>> num_islands([['1','1','0'],['1','0','0'],['0','0','1']])
    2
    """
    if not grid:
        return 0
    R, C = len(grid), len(grid[0])
    seen = [[False] * C for _ in range(R)]
    count = 0
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            x, y = stack.pop()
            if 0 <= x < R and 0 <= y < C and grid[x][y] == '1' and not seen[x][y]:
                seen[x][y] = True
                stack.extend([(x+1,y),(x-1,y),(x,y+1),(x,y-1)])
    for r in range(R):
        for c in range(C):
            if grid[r][c] == '1' and not seen[r][c]:
                count += 1
                dfs(r, c)
    return count
```

