def quickselect(nums, k):
    def select(arr, k):
        if len(arr) == 1:
            return arr[0]
        pivot = arr[len(arr) // 2]
        lo = [x for x in arr if x < pivot]
        eq = [x for x in arr if x == pivot]
        hi = [x for x in arr if x > pivot]
        if k <= len(lo):
            return select(lo, k)
        if k <= len(lo) + len(eq):
            return pivot
        return select(hi, k - len(lo) - len(eq))
    return select(nums, k)
```

